CREATE TABLE "assertions" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"subject_type" "subject_type" NOT NULL,
	"subject_id" text NOT NULL,
	"facet" "facet",
	"abstraction_level" "abstraction_level",
	"text" text NOT NULL,
	"embedding" vector(1024),
	"embedding_model" text,
	"source_type" "source_type" NOT NULL,
	"source_artifact_id" text,
	"text_hash" text,
	"start_off" integer,
	"end_off" integer,
	"quote" text,
	"prefix" text,
	"suffix" text,
	"provenance" jsonb NOT NULL,
	"extraction_run_id" uuid,
	"confidence" "confidence" DEFAULT 'extracted' NOT NULL,
	"evidence_type" "evidence_type",
	"status" "assertion_status" DEFAULT 'active' NOT NULL,
	"superseded_by" uuid,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "selectors_with_text" CHECK (("assertions"."text_hash" is null) = ("assertions"."start_off" is null and "assertions"."end_off" is null and "assertions"."quote" is null and "assertions"."prefix" is null and "assertions"."suffix" is null)),
	CONSTRAINT "facet_null_only_annotation" CHECK ("assertions"."facet" is not null or "assertions"."source_type" = 'annotation'),
	CONSTRAINT "confirmed_is_human" CHECK ("assertions"."confidence" <> 'confirmed' or "assertions"."source_type" in ('annotation', 'subject_edit')),
	CONSTRAINT "corroborated_names_source" CHECK ("assertions"."confidence" <> 'corroborated' or jsonb_exists("assertions"."provenance", 'corroborated_by')),
	CONSTRAINT "embedding_has_model" CHECK (("assertions"."embedding" is null) = ("assertions"."embedding_model" is null))
);
