-- Partial HNSW indexes, one per facet family. Partial-by-family sidesteps
-- pgvector's filtered-scan under-return; the `embedding IS NOT NULL`
-- predicate is repeated in every similarity query because an index scan
-- drops null-embedding rows while a sequential scan sorts them last, and
-- dev and prod would otherwise disagree.
CREATE INDEX "assertions_purpose_hnsw" ON "assertions" USING hnsw ("embedding" vector_cosine_ops) WHERE "status" = 'active' AND "embedding" IS NOT NULL AND "facet" = 'purpose';--> statement-breakpoint
-- The mechanism family is enumerated rather than matched with LIKE: casting
-- an enum to text is not IMMUTABLE and Postgres refuses it in an index
-- predicate. The vocabulary is closed, so the list is exact.
CREATE INDEX "assertions_mechanism_hnsw" ON "assertions" USING hnsw ("embedding" vector_cosine_ops) WHERE "status" = 'active' AND "embedding" IS NOT NULL AND "facet" IN ('mechanism', 'mechanism.product', 'mechanism.distribution', 'mechanism.revenue', 'mechanism.capability', 'mechanism_commanded', 'mechanism_sought');--> statement-breakpoint
CREATE INDEX "assertions_evidence_hnsw" ON "assertions" USING hnsw ("embedding" vector_cosine_ops) WHERE "status" = 'active' AND "embedding" IS NOT NULL AND "facet" = 'evidence';--> statement-breakpoint
CREATE INDEX "assertions_context_hnsw" ON "assertions" USING hnsw ("embedding" vector_cosine_ops) WHERE "status" = 'active' AND "embedding" IS NOT NULL AND "facet" IN ('constraint', 'domain', 'evaluation');--> statement-breakpoint

